function text(value) {
  return String(value ?? 'Not recorded').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\\`*_{}\[\]()!#|~]/g, char => '&#' + char.charCodeAt(0) + ';').replace(/\r?\n/g, '<br>');
}
function objects(result) { return result.rows.map(row => Object.fromEntries(result.columns.map((name, i) => [name, row[i]]))); }
function table(result, empty) {
  return (result.rows.length ? markdown.table({ ...result, rows: result.rows.map(row => row.map(value => text(value))) }) : empty) + (result.truncated ? '\n\nResults truncated at 500 rows; use narrower typed queries.' : '');
}
function section(title, result, empty) { parts.push('### ' + title, table(result, empty)); }
const latest = silo.sql("SELECT r.* FROM source_audit_runs r WHERE NOT EXISTS (SELECT 1 FROM source_audit_runs newer WHERE newer.package_path = r.package_path AND (newer.created_at > r.created_at OR (newer.created_at = r.created_at AND newer.run_id > r.run_id))) ORDER BY r.package_path");
const parts = ['# Source audit overview', 'Each package uses its newest run by created_at, then run_id descending, regardless of status. Finding counts and details for a run use retained observations. Current findings are labeled separately. Use the typed source-audit queries with package and run for explicit selection. Zero findings does not establish completion.'];
if (!latest.rows.length) parts.push('No audit runs.');
if (latest.truncated) parts.push('Package list truncated at 500 rows; use source-audit-runs for a specific package.');
for (const run of objects(latest)) {
  const input = { package: run.package_path, run: run.run_id };
  parts.push('## Package: ' + text(run.package_path), 'Run: ' + text(run.run_id) + '; status: ' + text(run.status), 'Source commit: ' + text(run.commit_sha) + '; dirty worktree: ' + (run.worktree_dirty ? 'yes — commit alone does not identify inspected source. ' + text(run.worktree_notes) : 'no'), 'Scope: ' + text(run.scope), 'Exclusions: ' + text(run.exclusions));
parts.push('Scan command: ' + text(run.scan_command), run.scan_artifact === null ? 'No scan artifact. Metrics are unavailable until a successful scan is recorded.' : 'Scan artifact (repository-relative): ' + text(run.scan_artifact));
  if (run.summary !== null) parts.push('Stored summary: ' + text(run.summary));
  section('Recorded run counts and coverage', silo.query('source-audit-summary', input), 'No recorded summary.');
  const hotspots = silo.query('source-audit-hotspots', input);
  section('Top hotspots — prioritization, not proof of defects', { ...hotspots, rows: hotspots.rows.slice(0, 10) }, 'No recorded scan metrics.');
  if (hotspots.rows.length > 10) parts.push('Showing the first 10 hotspots; use source-audit-hotspots for more.');
  section('Coverage inventory', silo.sql("SELECT c.key AS inventory_index, c.value AS review_unit FROM source_audit_runs r, json_each(r.coverage) c WHERE r.package_path = :package AND r.run_id = :run ORDER BY c.key", input), 'No inventory recorded; coverage is unknown.');
  section('Remaining work', silo.sql("SELECT w.key AS item, w.value AS remaining_work FROM source_audit_runs r, json_each(r.remaining_work) w WHERE r.package_path = :package AND r.run_id = :run ORDER BY w.key", input), 'No remaining work recorded; this alone does not mean complete.');
  const findings = silo.query('source-audit-findings', input);
  section('Highest-priority recorded assessments', { ...findings, rows: findings.rows.slice(0, 10) }, 'No findings recorded as evaluated in this run.');
  if (findings.rows.length > 10) parts.push('Showing the first 10 assessments; use source-audit-findings for more.');
}
return parts.join('\n\n');

