const parts = ['# Source audit review queue', 'Each package uses its newest run by created_at, then run_id descending, regardless of status. Finding counts and details for a run use retained observations. Current findings are labeled separately. Use the typed source-audit queries with package and run for explicit selection. Zero findings does not establish completion.'];
if (!latest.rows.length) parts.push('No audit runs.');
if (latest.truncated) parts.push('Package list truncated at 500 rows; use source-audit-runs for a specific package.');
for (const run of objects(latest)) {
  const input = { package: run.package_path, run: run.run_id };
  parts.push('## Package: ' + text(run.package_path), 'Run: ' + text(run.run_id) + '; status: ' + text(run.status), 'Source commit: ' + text(run.commit_sha) + '; dirty worktree: ' + (run.worktree_dirty ? 'yes — commit alone does not identify inspected source. ' + text(run.worktree_notes) : 'no'), 'Scope: ' + text(run.scope), 'Exclusions: ' + text(run.exclusions));
parts.push('Priority combines recorded review priority and high-priority scan hotspots. Complexity is a review signal, not proof of a defect. Excluded checks remain listed and do not count as reviewed.');
  section('Incomplete checks and exclusions', silo.query('source-audit-next-review', input), 'No incomplete units recorded; inspect inventory before concluding coverage is complete.');
  section('Inventory and check state', silo.query('source-audit-summary', input), 'No recorded inventory.');
  const hotspots = silo.query('source-audit-hotspots', input);
  const pending = objects(hotspots).filter(h => h.priority === 'high' && (JSON.parse(h.coverage).length === 0 || JSON.parse(h.coverage).some(c => !['reviewed_no_findings','reviewed_with_findings'].includes(c.implementation) || !['reviewed_no_findings','reviewed_with_findings','not_applicable'].includes(c.api))));
  section('High-priority hotspots without full recorded coverage', { ...hotspots, rows: pending.map(h => hotspots.columns.map(c => h[c])) }, run.scan_artifact === null ? 'No scan artifact; hotspot priority is unavailable.' : 'No uncovered high-priority hotspots in the returned scan rows.');
  section('Outstanding areas, leads and blockers', silo.sql("SELECT json_extract(w.value, '$.kind') AS kind, json_extract(w.value, '$.file_path') AS file_path, json_extract(w.value, '$.text') AS detail FROM source_audit_runs r, json_each(r.remaining_work) w WHERE r.package_path = :package AND r.run_id = :run ORDER BY kind, file_path, w.key", input), 'No outstanding work recorded.');
  section('Run findings needing verification and separate leads', silo.query('source-audit-needs-verification', input), 'No run assessments needing verification or unresolved leads recorded.');
  section('Current findings not recorded as checked in this run', silo.sql("SELECT f.finding_id, f.title, f.confidence, f.last_checked_run_id FROM source_audit_findings f WHERE f.package_path = :package AND NOT EXISTS (SELECT 1 FROM source_audit_observations o WHERE o.finding_id = f.finding_id AND o.run_id = :run) ORDER BY f.file_path, f.finding_id", input), 'All current findings have a recorded observation in this run.');
}
return parts.join('\n\n');

