const latest = silo.sql("SELECT r.* FROM source_audit_runs r WHERE NOT EXISTS (SELECT 1 FROM source_audit_runs newer WHERE newer.package_path = r.package_path AND (newer.created_at > r.created_at OR (newer.created_at = r.created_at AND newer.run_id > r.run_id))) ORDER BY r.package_path");
const parts = ['# Source audit findings', 'Each package uses its newest run by created_at, then run_id descending, regardless of status. Finding counts and details for a run use retained observations. Current findings are labeled separately. Use the typed source-audit queries with package and run for explicit selection. Zero findings does not establish completion.'];
if (!latest.rows.length) parts.push('No audit runs.');
if (latest.truncated) parts.push('Package list truncated at 500 rows; use source-audit-runs for a specific package.');
for (const run of objects(latest)) {
  const input = { package: run.package_path, run: run.run_id };
  parts.push('## Package: ' + text(run.package_path), 'Run: ' + text(run.run_id) + '; status: ' + text(run.status), 'Source commit: ' + text(run.commit_sha) + '; dirty worktree: ' + (run.worktree_dirty ? 'yes — commit alone does not identify inspected source. ' + text(run.worktree_notes) : 'no'), 'Scope: ' + text(run.scope), 'Exclusions: ' + text(run.exclusions));
const result = silo.query('source-audit-findings', input);
  if (!result.rows.length) parts.push('No findings recorded as evaluated in this run.');
  if (result.truncated) parts.push('Assessments truncated at 500 rows; narrow source-audit-findings by file or category.');
  const assessments = objects(result);
  for (const category of ['complexity','performance','comments','tsdoc','other']) {
    const group = assessments.filter(f => f.category === category);
    if (!group.length) continue;
    parts.push('### Category: ' + category);
    for (const f of group) {
      parts.push('#### ' + text(f.finding_id) + ': ' + text(f.title));
      for (const key of ['category','severity','confidence','file_path','related_symbols','evidence','issue','impact','recommendation','notes']) parts.push(key + ': ' + text(f[key]));
    }
  }
  section('Current findings not recorded as checked in this run', silo.sql("SELECT f.finding_id, f.title, f.category, f.severity, f.confidence, f.file_path, f.last_checked_run_id FROM source_audit_findings f WHERE f.package_path = :package AND NOT EXISTS (SELECT 1 FROM source_audit_observations o WHERE o.finding_id = f.finding_id AND o.run_id = :run) ORDER BY CASE f.severity WHEN 'high' THEN 0 WHEN 'medium' THEN 1 ELSE 2 END, CASE f.confidence WHEN 'high' THEN 0 WHEN 'medium' THEN 1 ELSE 2 END, f.file_path, f.finding_id", input), 'No current findings lacking an observation in this run.');
}
return parts.join('\n\n');
